========== src/pages/quiz/[slug].astro ==========
     299 src/pages/quiz/[slug].astro
---
import Layout from '@/layouts/base.astro';
import GatedQuizStepper from '@/components/quiz/GatedQuizStepper';
import QuizIcon from '@/lib/quiz-engine/components/QuizIcon';
import QuizIntroCard from '@/lib/quiz-engine/components/QuizIntroCard';
import Logo from '@/assets/images/global/APR-Logo-2020_Horizontal_RGB.svg';
import { Image } from 'astro:assets';
import { getCollection, getEntry } from 'astro:content';

export async function getStaticPaths() {
  const quizzes = await getCollection('quizzes');
  return quizzes.map((quiz) => ({ params: { slug: quiz.id } }));
}

const { slug } = Astro.params;
const entry = await getEntry('quizzes', slug!);
if (!entry) {
  return new Response(null, { status: 404, statusText: 'Not found' });
}

const data = entry.data;
const persuasionParagraphs = data.persuasion
  ? data.persuasion
      .split(/\n\s*\n/)
      .map((p: string) => p.trim())
      .filter(Boolean)
  : [];
const persuasionBullets = data.persuasionBullets ?? [];
const howItWorks = data.howItWorks ?? [];
// Balance the section cards: 3 (or any multiple of 3) reads best as a 3-up row;
// everything else stays 2-up (so 4 cards are a tidy 2x2 rather than 3+1).
const sectionColsClass =
  data.sections.length % 3 === 0 ? 'md:grid-cols-3' : 'md:grid-cols-2';
// Reflective (map-move) quizzes have no "right" answer, so suppress the
// correct/incorrect highlighting the band quizzes use.
const showCorrectness = (data.resultStyle ?? 'band') !== 'map-move';
const heroButtonLabel = data.heroButtonLabel ?? 'Start the quiz';
// Says when the email is asked for, which differs by `capturePosition`, so the
// hero never promises "at the end" on a quiz that gates at the start.
const heroButtonNote =
  data.heroButtonNote ??
  (data.capturePosition === 'start'
    ? 'Free. You’ll add your email before you start.'
    : 'Free. To see your results, you’ll add your email at the end.');
// A start-gated quiz puts the opt-in panel on the cover itself, so the cover
// needs no CTA button of its own: the panel is the call to action.
const showHeroButton = data.capturePosition !== 'start';

// Tints for the "how it works" chips. Colour here is warmth and sequence only,
// so it is deliberately kept out of the semantic roles the result page uses.
const stepToneClasses: Record<string, string> = {
  accent: 'bg-quiz-accent-tint text-quiz-accent-strong',
  valuable: 'bg-quiz-valuable-tint text-quiz-valuable-strong',
  slipping: 'bg-quiz-slipping-tint text-quiz-slipping-strong',
  alt: 'bg-quiz-step3-tint text-quiz-step3-strong',
};
const stepLabelClasses: Record<string, string> = {
  accent: 'text-quiz-accent-strong',
  valuable: 'text-quiz-valuable-strong',
  slipping: 'text-quiz-slipping-strong',
  alt: 'text-quiz-step3-strong',
};
---

<Layout
  title={data.title}
  description={data.description ?? data.title}
  includeCoursesCTA={false}
  hideChrome={true}
>
  <div class="min-h-screen bg-quiz-page">
    <header class="border-b-[0.5px] border-quiz-hairline">
      <div class="mx-auto max-w-[680px] px-4 py-3">
        <a href="/" aria-label="Agile Pain Relief home">
          <img src={Logo.src} alt="Agile Pain Relief" class="h-9 w-auto" />
        </a>
      </div>
    </header>

    <div class="mx-auto max-w-[680px] px-4 py-10 md:py-14">
      <div data-quiz-chrome>
        <section class="mb-8">
          <h1
            class="max-w-[32ch] text-3xl leading-tight font-bold text-quiz-ink md:text-4xl"
          >
            {data.heroHeading ?? data.title}
          </h1>
          {
            data.heroBody ? (
              <p class="mt-4 max-w-[52ch] text-base leading-relaxed text-quiz-ink-secondary">
                {data.heroBody}
              </p>
            ) : null
          }
          {
            persuasionParagraphs.map((paragraph) => (
              <p class="mt-3 max-w-[52ch] text-base leading-relaxed text-quiz-ink-muted">
                {paragraph}
              </p>
            ))
          }
          {
            showHeroButton ? (
              <div class="mt-7">
                <button
                  type="button"
                  data-quiz-start
                  class="rounded-lg bg-quiz-ink px-5 py-2.5 text-base font-medium text-white transition hover:opacity-90 focus:ring-2 focus:ring-quiz-accent-strong focus:ring-offset-2 focus:outline-none"
                >
                  {heroButtonLabel}
                </button>
                {heroButtonNote ? (
                  <p class="mt-3 text-sm text-quiz-ink-muted">
                    {heroButtonNote}
                  </p>
                ) : null}
              </div>
            ) : null
          }
        </section>

        {/* What the taker gets, shown before they hand anything over. */}
        {
          howItWorks.length > 0 ? (
            <section
              class="mb-8 grid gap-3.5"
              style="grid-template-columns: repeat(auto-fit, minmax(180px, 1fr))"
            >
              {howItWorks.map((step) => (
                <div class="rounded-xl border-[0.5px] border-quiz-hairline bg-quiz-card p-4">
                  <span
                    class:list={[
                      'mb-3 flex h-10 w-10 items-center justify-center rounded-[10px]',
                      stepToneClasses[step.tone] ?? stepToneClasses.accent,
                    ]}
                  >
                    <QuizIcon name={step.icon ?? ''} size={22} />
                  </span>
                  {step.label ? (
                    <p
                      class:list={[
                        'mb-1 text-sm',
                        stepLabelClasses[step.tone] ?? stepLabelClasses.accent,
                      ]}
                    >
                      {step.label}
                    </p>
                  ) : null}
                  <h3 class="text-lg font-bold text-quiz-ink">{step.title}</h3>
                  {step.body ? (
                    <p class="mt-1 text-sm leading-relaxed text-quiz-ink-secondary">{step.body}</p>
                  ) : null}
                </div>
              ))}
            </section>
          ) : null
        }

        {/* Section cards and proof bullets are the pre-"how it works" cover
            layout, kept for quizzes that don't declare a steps strip. */}
        {
          howItWorks.length === 0 && data.sections.length > 0 ? (
            <section class="mb-8">
              {data.categoriesHeading ? (
                <h2 class="mb-5 text-2xl font-bold text-quiz-ink">
                  {data.categoriesHeading}
                </h2>
              ) : null}
              <div class:list={['grid grid-cols-1 gap-3.5', sectionColsClass]}>
                {data.sections.map((section) => (
                  <div class="rounded-xl border-[0.5px] border-quiz-hairline bg-quiz-card p-4">
                    {section.image ? (
                      typeof section.image === 'string' ? (
                        <img
                          src={section.image}
                          alt=""
                          class="mb-3 h-24 w-full rounded-lg object-contain"
                          loading="lazy"
                        />
                      ) : (
                        <Image
                          src={section.image}
                          alt=""
                          class="mb-3 h-24 w-full rounded-lg object-contain"
                          loading="lazy"
                        />
                      )
                    ) : null}
                    <h3 class="text-lg font-bold text-quiz-ink">{section.label}</h3>
                    {section.blurb ? (
                      <p class="mt-1 text-sm leading-relaxed text-quiz-ink-secondary">{section.blurb}</p>
                    ) : null}
                  </div>
                ))}
              </div>
            </section>
          ) : null
        }

        {
          howItWorks.length === 0 && persuasionBullets.length > 0 ? (
            <section class="mb-8 rounded-xl bg-quiz-context-panel p-4 md:p-5">
              <ul class="grid grid-cols-1 gap-2.5 text-base text-quiz-ink-secondary sm:grid-cols-2">
                {persuasionBullets.map((bullet) => (
                  <li class="flex items-start gap-2">
                    <span
                      aria-hidden="true"
                      class="text-quiz-valuable-strong mt-0.5"
                    >
                      ✓
                    </span>
                    <span>{bullet}</span>
                  </li>
                ))}
              </ul>
            </section>
          ) : null
        }

        {/* On a start gate the reassurance sits directly above the opt-in. The
            privacy worry ("nobody else sees what you pick") is the thing that
            stops someone handing over an email, so it has to be read before the
            ask, and it leaves the opt-in as the last thing on the page. The
            stepper has no intro step in that case, so the card lives here and
            hides with the rest of the cover once the questions begin. */}
        {
          data.capturePosition === 'start' &&
          (data.introHeading || data.intro) ? (
            <section class="mb-8">
              <QuizIntroCard
                title={data.introHeading}
                body={data.intro}
                icon={data.introIcon}
              />
            </section>
          ) : null
        }
      </div>

      <section id="quiz" class="scroll-mt-24">
        <GatedQuizStepper
          client:load
          quiz={data}
          submissionTags={data.submissionTags}
          levelTagPrefix={data.levelTagPrefix}
          quizSlug={entry.id}
          introTitle={data.introHeading}
          introIcon={data.introIcon}
          startButtonLabel={heroButtonLabel}
          submitButtonLabel={data.submitButtonLabel}
          showCorrectness={showCorrectness}
          captureHeading={data.captureHeading}
          captureBody={data.captureBody}
          captureButtonLabel={data.captureButtonLabel}
          captureFootnote={data.captureFootnote}
        />
      </section>
    </div>
  </div>
</Layout>

<script>
  // Hide the cover's marketing chrome once the taker moves past the first step.
  // The stepper fires `quiz:step-changed` on every transition, including
  // back-navigation, so the chrome re-appears if they return to the cover.
  // Keyed on the step index rather than its kind, because which step comes
  // first depends on the quiz's capture position.
  // querySelectorAll rather than querySelector: the cover is one region today,
  // but a quiz that puts a block on the far side of the opt-in would need both
  // to hide together, and a silently-unhidden region is an ugly failure.
  const chrome = document.querySelectorAll<HTMLElement>('[data-quiz-chrome]');
  if (chrome.length > 0) {
    window.addEventListener('quiz:step-changed', (event) => {
      const detail = (event as CustomEvent<{ index: number }>).detail;
      const display = detail?.index === 0 ? '' : 'none';
      chrome.forEach((region) => {
        region.style.display = display;
      });
    });
  }

  // The cover's own CTA advances the stepper past its first step. Only rendered
  // when the quiz doesn't gate on the cover (a gate is its own call to action).
  document
    .querySelectorAll<HTMLButtonElement>('[data-quiz-start]')
    .forEach((button) => {
      button.addEventListener('click', () => {
        window.dispatchEvent(new CustomEvent('quiz:start-requested'));
      });
    });
</script>

<script is:inline define:vars={{ quizSlug: entry.id }}>
  window.addEventListener('quiz:started', () => {
    if (typeof posthog !== 'undefined') {
      posthog.capture('quiz_started', { quiz: quizSlug });
    }
  });
</script>

