import Layout from '@/layouts/base.astro';
import GatedQuizStepper from '@/components/quiz/GatedQuizStepper';
import QuizIcon from '@/lib/quiz-engine/components/QuizIcon';
import QuizIntroCard from '@/lib/quiz-engine/components/QuizIntroCard';
import Logo from '@/assets/images/global/APR-Logo-2020_Horizontal_RGB.svg';
import { Image } from 'astro:assets';
import { getCollection, getEntry } from 'astro:content';

export async function getStaticPaths() {
  const quizzes = await getCollection('quizzes');
  return quizzes.map((quiz) => ({ params: { slug: quiz.id } }));
}

const { slug } = Astro.params;
const entry = await getEntry('quizzes', slug!);
if (!entry) {
  return new Response(null, { status: 404, statusText: 'Not found' });
}

const data = entry.data;
const persuasionParagraphs = data.persuasion
  ? data.persuasion
      .split(/\n\s*\n/)
      .map((p: string) => p.trim())
      .filter(Boolean)
  : [];
const persuasionBullets = data.persuasionBullets ?? [];
const howItWorks = data.howItWorks ?? [];
// Balance the section cards: 3 (or any multiple of 3) reads best as a 3-up row;
// everything else stays 2-up (so 4 cards are a tidy 2x2 rather than 3+1).
const sectionColsClass =
  data.sections.length % 3 === 0 ? 'md:grid-cols-3' : 'md:grid-cols-2';
// Reflective (map-move) quizzes have no "right" answer, so suppress the
// correct/incorrect highlighting the band quizzes use.
const showCorrectness = (data.resultStyle ?? 'band') !== 'map-move';
const heroButtonLabel = data.heroButtonLabel ?? 'Start the quiz';
// Says when the email is asked for, which differs by `capturePosition`, so the
// hero never promises "at the end" on a quiz that gates at the start.
const heroButtonNote =
  data.heroButtonNote ??
  (data.capturePosition === 'start'
    ? 'Free. You’ll add your email before you start.'
    : 'Free. To see your results, you’ll add your email at the end.');
// A start-gated quiz puts the opt-in panel on the cover itself, so the cover
// needs no CTA button of its own: the panel is the call to action.
const showHeroButton = data.capturePosition !== 'start';

// Tints for the "how it works" chips. Colour here is warmth and sequence only,
// so it is deliberately kept out of the semantic roles the result page uses.
const stepToneClasses: Record<string, string> = {
  accent: 'bg-quiz-accent-tint text-quiz-accent-strong',
  valuable: 'bg-quiz-valuable-tint text-quiz-valuable-strong',
  slipping: 'bg-quiz-slipping-tint text-quiz-slipping-strong',
  alt: 'bg-quiz-step3-tint text-quiz-step3-strong',
};
const stepLabelClasses: Record<string, string> = {
  accent: 'text-quiz-accent-strong',
  valuable: 'text-quiz-valuable-strong',
  slipping: 'text-quiz-slipping-strong',
  alt: 'text-quiz-step3-strong',
};
