        {
          howItWorks.length > 0 ? (
            <section
              class="mb-8 grid gap-3.5"
              style="grid-template-columns: repeat(auto-fit, minmax(180px, 1fr))"
            >
              {howItWorks.map((step) => (
                <div class="rounded-xl border-[0.5px] border-quiz-hairline bg-quiz-card p-4">
