                  ) : null}
                  <h3 class="text-lg font-bold text-quiz-ink">{step.title}</h3>
                  {step.body ? (
                    <p class="mt-1 text-sm leading-relaxed text-quiz-ink-secondary">{step.body}</p>
                  ) : null}
                </div>
              ))}
            </section>
          ) : null
        }

        {/* Section cards and proof bullets are the pre-"how it works" cover
            layout, kept for quizzes that don't declare a steps strip. */}
        {
          howItWorks.length === 0 && data.sections.length > 0 ? (
            <section class="mb-8">
              {data.categoriesHeading ? (
                <h2 class="mb-5 text-2xl font-bold text-quiz-ink">
                  {data.categoriesHeading}
                </h2>
              ) : null}
              <div class:list={['grid grid-cols-1 gap-3.5', sectionColsClass]}>
                {data.sections.map((section) => (
                  <div class="rounded-xl border-[0.5px] border-quiz-hairline bg-quiz-card p-4">
                    {section.image ? (
                      typeof section.image === 'string' ? (
                        <img
                          src={section.image}
                          alt=""
                          class="mb-3 h-24 w-full rounded-lg object-contain"
                          loading="lazy"
                        />
                      ) : (
                        <Image
                          src={section.image}
                          alt=""
                          class="mb-3 h-24 w-full rounded-lg object-contain"
                          loading="lazy"
                        />
                      )
                    ) : null}
                    <h3 class="text-lg font-bold text-quiz-ink">{section.label}</h3>
                    {section.blurb ? (
                      <p class="mt-1 text-sm leading-relaxed text-quiz-ink-secondary">{section.blurb}</p>
                    ) : null}
                  </div>
                ))}
              </div>
            </section>
          ) : null
        }

        {
          howItWorks.length === 0 && persuasionBullets.length > 0 ? (
            <section class="mb-8 rounded-xl bg-quiz-context-panel p-4 md:p-5">
              <ul class="grid grid-cols-1 gap-2.5 text-base text-quiz-ink-secondary sm:grid-cols-2">
                {persuasionBullets.map((bullet) => (
                  <li class="flex items-start gap-2">
