import {
  ArrowDownRight,
  ArrowRight,
  ArrowUpRight,
  Clock,
  Construction,
  EyeOff,
  ListChecks,
  MapPinned,
  Network,
  Target,
  Ticket,
  UserRoundCog,
  Users,
  Wrench,
  type LucideIcon,
} from 'lucide-react';

/**
 * The quiz engine's icon vocabulary. Quizzes reference icons by *concept*
 * (`icon: 'admin'`) rather than by a library's icon name, so the whole set can
 * be re-pointed at a different art family by editing this one map. Nothing else
 * in the engine, and nothing in any quiz's frontmatter, knows which library is
 * behind these names.
 *
 * Currently Lucide (already a site dependency, one human-authored family,
 * legible at the 18-22px inline sizes this design uses).
 */
const ICONS = {
  // Concepts the map and the questions talk about.
  time: Clock,
  admin: Ticket,
  people: Users,
  productOwner: UserRoundCog,
  root: Target,
  system: Network,
  handsOn: Wrench,
  blocker: Construction,
  // Structural icons the engine's own chrome uses.
  steps: ListChecks,
  map: MapPinned,
  next: ArrowRight,
  privacy: EyeOff,
  gaining: ArrowUpRight,
  slipping: ArrowDownRight,
} satisfies Record<string, LucideIcon>;

export type QuizIconName = keyof typeof ICONS;

export function isQuizIconName(name: string): name is QuizIconName {
  return name in ICONS;
}

interface Props {
  name: string;
  /** Pixel size. 18-22 inline, 22 inside a step chip. */
  size?: number;
  className?: string;
}

/**
 * Renders a named icon, or nothing at all if the name is unknown. A missing
 * icon must never break a result page: colour, label and position already carry
 * the meaning, so the icon is reinforcement.
 */
export default function QuizIcon({ name, size = 18, className }: Props) {
  if (!isQuizIconName(name)) return null;
  const Icon = ICONS[name];
  return (
    <Icon size={size} strokeWidth={1.75} className={className} aria-hidden="true" />
  );
}

